<script>
function copyText() {
    // Get the content to copy
    const contentArea = document.getElementById('textToCopy');

    // Create a temporary textarea to handle the formatted content
    const textarea = document.createElement('textarea');
    textarea.value = contentArea.innerText.replace(/^\s+|\s+$/g, ''); // Trim excess whitespace
    document.body.appendChild(textarea);

    const button = document.getElementById('copyButton');
    const buttonText = button.querySelector('.button-text');

    try {
        textarea.select();
        document.execCommand('copy');

        // Visual feedback
        button.classList.add('copied');
        buttonText.textContent = 'Copied!';

        // Reset after 2 seconds
        setTimeout(() => {
            button.classList.remove('copied');
            buttonText.textContent = 'Copy Text';
        }, 2000);
    } catch (err) {
        console.error('Failed to copy text:', err);
    } finally {
        document.body.removeChild(textarea);
    }
}
